const char* get(Text id, int lang) {
    int l = (lang >= 0) ? lang : lcs::settings::get().game_language;
    l = std::clamp(l, 0, kNumLangs - 1);
    const size_t idx = static_cast<size_t>(id);
    if (idx >= std::size(kTable)) return "";
    return kTable[idx][l];
}

